 owner = await installOwner(); runtime = await createAgentSessionRuntime(createRuntime, { cwd: root, agentDir: agent, sessionManager: reopened }); await runtime.session.bindExtensions({ mode, uiContext: ui as never }); assert.equal(runtime.session.model?.provider, "openai"); assert.equal(runtime.session.model?.id, "gpt-6.1-sol"); const usageBefore = runtime.session.getContextUsage(); assert.ok(usageBefore && usageBefore.tokens && usageBefore.tokens > 0); runtime.session.subscribe(event => { if (event.type === "compaction_end" && event.aborted) compactionCancels++; });
